interface Plugin { onEvent(event: string): void }

class Framework {
  private plugins: Plugin[] = []
  register(p: Plugin) { this.plugins.push(p) }
  trigger(e: string) { this.plugins.forEach(p => p.onEvent(e)) }
}

// Application registers plugins and does not poll the framework

type Plugin = { handle(evt: string): void }

class Host {
  private plugins: Plugin[] = []
  register(p: Plugin) { this.plugins.push(p) }
  emit(evt: string) { this.plugins.forEach(p => p.handle(evt)) }
}

// Plugins rely on the host to drive their lifecycle and execution

/* Version A: application calls framework methods directly */
class App {
  doWork(host: Host) {
    host.startTask()
    host.processItem('x')
    host.finishTask()
  }
}

/* Version B: framework provides callbacks the application implements */
class Host2 {
  run(callbacks: { onStart(): void, onItem(item: string): void, onEnd(): void }) {
    callbacks.onStart()
    callbacks.onItem('x')
    callbacks.onEnd()
  }
}
